const color1 = document.getElementById('color1');
const color2 = document.getElementById('color2');
const preview = document.getElementById('preview');
const direction = document.getElementById('direction');
const cssCode = document.getElementById('css-code');
const rgbCode = document.getElementById('rgb-code');
const randomBtn = document.getElementById('random');
const copyCssBtn = document.getElementById('copy-css');
const copyRgbBtn = document.getElementById('copy-rgb');
const toast = document.getElementById('toast');

function hexToRgb(hex) {
    const value = hex.replace('#', '');
    const bigint = parseInt(value, 16);
    const r = (bigint >> 16) & 255;
    const g = (bigint >> 8) & 255;
    const b = bigint & 255;
    return 'rgb(' + r + ', ' + g + ', ' + b + ')';
}

function randomHex() {
    const letters = '0123456789ABCDEF';
    let color = '#';
    for (let i = 0; i < 6; i++) {
        color += letters[Math.floor(Math.random() * 16)];
    }
    return color;
}

function update() {
    const value = 'linear-gradient(' + direction.value + ', ' + color1.value + ', ' + color2.value + ')';
    preview.style.background = 'linear-gradient(' + direction.value + ', ' + color1.value + ', ' + color2.value + ')';
    cssCode.textContent = 'background: ' + value + ';';
    rgbCode.textContent = 'Color 1: ' + hexToRgb(color1.value) + '  |  Color 2: ' + hexToRgb(color2.value);
}

function showToast() {
    toast.classList.add('show');
    setTimeout(function () {
        toast.classList.remove('show');
    }, 1500);
}

function copyText(text) {
    const temp = document.createElement('textarea');
    temp.value = text;
    document.body.appendChild(temp);
    temp.select();
    try {
        document.execCommand('copy');
    } catch (e) {}
    document.body.removeChild(temp);
    showToast();
}

color1.addEventListener('input', update);
color2.addEventListener('input', update);
direction.addEventListener('change', update);

randomBtn.addEventListener('click', function () {
    color1.value = randomHex();
    color2.value = randomHex();
    update();
});

copyCssBtn.addEventListener('click', function () {
    copyText(cssCode.textContent);
});

copyRgbBtn.addEventListener('click', function () {
    copyText(rgbCode.textContent);
});

update();

