arguments.content:
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: #fafafa;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    color: #262626;
}

a {
    text-decoration: none;
    color: inherit;
}

.main {
    flex: 1;
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 30px 0;
}

.container {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 32px;
    max-width: 875px;
    width: 100%;
    padding: 0 20px;
}

/* ---------- Left column: phone mockup ---------- */

.phone-section {
    display: flex;
}

.phone-mockup {
    position: relative;
    width: 454px;
    height: 618px;
    flex-shrink: 0;
}

.phone-frame {
    position: absolute;
    top: 0;
    left: 0;
    width: 454px;
    height: 618px;
}

.phone-screen {
    position: absolute;
    top: 40px;
    left: 52px;
    width: 350px;
    height: 538px;
    animation: fadeSlide 1.2s ease-in-out infinite;
}

@keyframes fadeSlide {
    0%, 20% {
        opacity: 0;
        transform: translateY(8px);
    }
    35%, 70% {
        opacity: 1;
        transform: translateY(0);
    }
    95%, 100% {
        opacity: 0;
    }
}

/* ---------- Right column: login section ---------- */

.login-section {
    max-width: 350px;
    width: 100%;
}

.card {
    background-color: #fff;
    border: 1px solid rgba(219, 219, 219, 1);
    border-radius: 1px;
    padding: 20px 40px;
    margin-bottom: 10px;
    text-align: center;
}

.logo {
    font-family: "Satisfy", cursive;
    font-size: 44px;
    font-weight: 400;
    margin: 12px 0 24px;
    line-height: 1;
}

form {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 12px;
}

.input-group {
    position: relative;
}

.input-group input {
    width: 100%;
    padding: 10px 8px;
    background-color: #fafafa;
    border: 1px solid rgba(219, 219, 219, 1);
    border-radius: 3px;
    font-size: 12px;
    color: #262626;
    outline: none;
}

.input-group input:focus {
    border-color: #a8a8a8;
}

.input-group label {
    position: absolute;
    top: 50%;
    left: 9px;
    transform: translateY(-50%);
    font-size: 12px;
    color: #8e8e8e;
    pointer-events: none;
    transition: all 0.15s ease-out;
}

.input-group input:focus + label,
.input-group input:not(:placeholder-shown) + label {
    top: 5px;
    transform: none;
    font-size: 9px;
}

.login-btn {
    width: 100%;
    margin-top: 8px;
    padding: 8px 0;
    background-color: #0095f6;
    border: none;
    border-radius: 6px;
    color: #fff;
    font-size: 14px;
    font-weight: 600;
    text-align: center;
    cursor: pointer;
    transition: background-color 0.15s ease-out;
}

.login-btn:hover {
    background-color: #0077cc;
}

.divider {
    display: flex;
    align-items: center;
    gap: 14px;
    margin: 14px 0;
}

.divider .line {
    flex: 1;
    height: 1px;
    background-color: rgba(219, 219, 219, 1);
}

.divider .or-text {
    font-size: 13px;
    font-weight: 600;
    color: #8e8e8e;
}

.fb-login {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    font-size: 14px;
    font-weight: 600;
    color: #385185;
    margin-bottom: 18px;
}

.fb-icon {
    width: 20px;
    height: 20px;
}

.forgot-password {
    font-size: 12px;
    color: #00376b;
}

.signup-card p {
    font-size: 14px;
    padding: 7px 0;
}

.signup-link {
    color: #0095f6;
    font-weight: 600;
}

/* ---------- Get the app ---------- */

.get-app {
    text-align: center;
    margin-top: 12px;
}

.get-app p {
    font-size: 14px;
    margin-bottom: 12px;
}

.store-badges {
    display: flex;
    justify-content: center;
    gap: 8px;
}

.store-badge {
    height: 40px;
}

/* ---------- Footer ---------- */

.footer {
    width: 100%;
    max-width: 1000px;
    margin: 0 auto;
    padding: 20px 20px 40px;
    text-align: center;
    font-size: 12px;
    color: #8e8e8e;
}

.footer-links {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px 16px;
    margin-bottom: 14px;
}

.footer-group {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px 16px;
}

.footer-group a:hover {
    text-decoration: underline;
}

.language-select select {
    border: none;
    background: none;
    font-size: 12px;
    color: #8e8e8e;
    cursor: pointer;
    margin-left: 4px;
}

.copyright {
    font-size: 12px;
}

/* ---------- Responsive ---------- */

@media (max-width: 875px) {
    .phone-section {
        display: none;
    }

    .container {
        gap: 0;
    }
}

@media (max-width: 450px) {
    .main {
        padding: 0;
    }

    .card {
        border: none;
        background-color: #fafafa;
        padding: 20px 24px;
    }

    .get-app {
        margin-bottom: 40px;
    }

    .store-badge {
        height: 36px;
    }
}

