arguments.content:
const fs = require('fs');
const zlib = require('zlib');

const buf = fs.readFileSync(process.argv[2]);
let pos = 8;
let w, h, bitDepth, colorType, data = Buffer.alloc(0);
while (pos < buf.length) {
  const len = buf.readUInt32BE(pos);
  const type = buf.toString('ascii', pos + 4, pos + 8);
  const chunk = buf.slice(pos + 8, pos + 8 + len);
  if (type === 'IHDR') {
    w = chunk.readUInt32BE(0); h = chunk.readUInt32BE(4);
    bitDepth = chunk[8]; colorType = chunk[9];
  } else if (type === 'IDAT') {
    data = Buffer.concat([data, chunk]);
  } else if (type === 'IEND') break;
  pos += 12 + len;
}
const bpp = colorType === 6 ? 4 : 3;
const raw = zlib.inflateSync(data);
const stride = w * bpp + 1;
const px = Buffer.alloc(w * h * bpp);
let prev = Buffer.alloc(stride);
for (let y = 0; y < h; y++) {
  const row = raw.slice(y * stride, (y + 1) * stride);
  const filter = row[0];
  const line = Buffer.alloc(w * bpp);
  for (let i = 0; i < w * bpp; i++) {
    const x = row[i + 1];
    const a = i >= bpp ? line[i - bpp] : 0;
    const b = prev[i];
    const c = i >= bpp ? prev[i - bpp] : 0;
    let v;
    switch (filter) {
      case 0: v = x; break;
      case 1: v = x + a; break;
      case 2: v = x + b; break;
      case 3: v = x + ((a + b) >> 1); break;
      case 4: {
        const p = a + b - c;
        const pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
        v = x + (pa <= pb && pa <= pc ? a : pb <= pc ? b : c);
        break;
      }
    }
    line[i] = v & 255;
  }
  line.copy(px, y * w * bpp);
  prev = line;
}
const sample = (x, y) => {
  const i = (y * w + x) * bpp;
  return [px[i], px[i + 1], px[i + 2]];
};
const out = {};
for (const arg of process.argv.slice(3)) {
  const [name, sx, sy] = arg.split('=');
  out[name] = sample(+sx, +sy).join(',');
}
console.log(JSON.stringify({ w, h, colorType, bitDepth, ...out }));

