const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const W = 100, H = 100;
const OUT = process.argv[2];
fs.mkdirSync(OUT, { recursive: true });

const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length, 0);
  const typeBuf = Buffer.from(type, 'ascii');
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([typeBuf, data])), 0);
  return Buffer.concat([len, typeBuf, data, crc]);
}

function writePng(name, pixels) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(W, 0);
  ihdr.writeUInt32BE(H, 4);
  ihdr[8] = 8;   // bit depth
  ihdr[9] = 2;   // color type RGB
  const raw = Buffer.alloc(H * (1 + W * 3));
  for (let y = 0; y < H; y++) {
    raw[y * (1 + W * 3)] = 0;
    for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 3;
      raw[y * (1 + W * 3) + 1 + x * 3] = pixels[i];
      raw[y * (1 + W * 3) + 1 + x * 3 + 1] = pixels[i + 1];
      raw[y * (1 + W * 3) + 1 + x * 3 + 2] = pixels[i + 2];
    }
  }
  const idat = zlib.deflateSync(raw, { level: 9 });
  const buf = Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', idat),
    chunk('IEND', Buffer.alloc(0)),
  ]);
  fs.writeFileSync(path.join(OUT, name), buf);
}

const PIP = [
  [50, 50],                                     // 1
  [28, 28, 72, 72],                             // 2
  [28, 28, 50, 50, 72, 72],                     // 3
  [28, 28, 28, 72, 72, 28, 72, 72],             // 4
  [28, 28, 28, 72, 50, 50, 72, 28, 72, 72],     // 5
  [28, 28, 28, 72, 28, 50, 72, 28, 72, 50, 72, 72], // 6
];

const R = 9;   // pip radius
const BORD = 7; // border thickness

function makeFace(n) {
  const px = Buffer.alloc(W * H * 3);
  const set = (x, y, r, g, b) => {
    const i = (y * W + x) * 3;
    px[i] = r; px[i + 1] = g; px[i + 2] = b;
  };
  const insideRounded = (x, y) => {
    const rad = 16;
    let cx = x < rad ? 0 : (x >= W - rad ? W : x);
    let cy = y < rad ? 0 : (y >= H - rad ? H : y);
    const dx = x - cx, dy = y - cy;
    if (dx * dx + dy * dy > rad * rad && (x < rad || x >= W - rad) && (y < rad || y >= H - rad)) return false;
    while (cx === 0 || cy === 0 || cx === W || cy === H) {
      const dx2 = x - cx, dy2 = y - cy;
      if (cx === 0 && cy === 0 && dx2 * dx2 + dy2 * dy2 <= rad * rad) break;
      if (cx === 0 && cy === H && dx2 * dx2 + dy2 * dy2 <= rad * rad) break;
      if (cx === W && cy === 0 && dx2 * dx2 + dy2 * dy2 <= rad * rad) break;
      if (cx === W && cy === H && dx2 * dx2 + dy2 * dy2 <= rad * rad) break;
      break;
    }
    return x >= 0 && y >= 0 && x < W && y < H;
  };
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      set(x, y, 244, 245, 250);
    }
  }
  // rounded square border
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const inBorder = x >= 0 && y >= 0 && x < W && y < H &&
        (x < BORD || x >= W - BORD || y < BORD || y >= H - BORD);
      if (inBorder && simpleRounded(x, y)) set(x, y, 226, 227, 235);
    }
  }
  const pips = PIP[n - 1];
  for (let i = 0; i < pips.length; i += 2) {
    const cx = pips[i], cy = pips[i + 1];
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (x * x + y * y >= 0 && Math.hypot(x - cx, y - cy) <= R) {
          if (x >= 0 && y >= 0 && x < W && y < H) set(x, y, 20, 20, 35);
        }
      }
    }
  }
  return px;
}

function simpleRounded(x, y) {
  const rad = 14;
  // map to corners
  if (x < BORD || x >= W - BORD || y < BORD || y >= H - BORD) {
    // near corners check
    const cx = x < W / 2 ? 0 : W;
    const cy = y < H / 2 ? 0 : H;
    const nx = x < W / 2 ? Math.min(BORD, x) : W - x;
    const ny = y < H / 2 ? Math.min(BORD, y) : H - y;
    void cx; void cy;
    if (Math.hypot(x - (x < W / 2 ? BORD : W - BORD), y - (y < H / 2 ? BORD : H - BORD)) < rad) return false;
  }
  return true;
}

for (let n = 1; n <= 6; n++) writePng(`dice-${n}.png`, makeFace(n));
console.log('wrote', fs.readdirSync(OUT).filter(f => f.startsWith('dice')).join(', '));

