* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    min-height: 100vh;
    background: url('back.jpg') no-repeat center / cover fixed;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.game-container {
    width: 100%;
    max-width: 1000px;
    text-align: center;
}

.game-title {
    font-size: 2.6rem;
    color: #fff;
    text-shadow: 0 4px 12px rgba(0, 0, 0, 0.55);
    letter-spacing: 1px;
}

.game-subtitle {
    color: rgba(255, 255, 255, 0.9);
    margin: 6px 0 26px;
    font-size: 1.05rem;
    text-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
}

.game-board {
    position: relative;
    display: flex;
    min-height: 460px;
    background: rgba(255, 255, 255, 0.95);
    border-radius: 18px;
    overflow: hidden;
    box-shadow: 0 25px 60px rgba(0, 0, 0, 0.35);
}

.player-panel {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 34px 20px;
    transition: background 0.35s ease;
}

.player-panel.active {
    background: rgba(247, 246, 237, 0.9);
}

.player-name {
    font-size: 1.5rem;
    font-weight: 700;
    color: #333;
    text-transform: uppercase;
    letter-spacing: 2px;
}

.player-panel.active .player-name::after {
    content: ' •';
    color: #f2494a;
}

.total-score {
    font-size: 5.5rem;
    font-weight: 700;
    color: #f2494a;
    margin: 14px 0 30px;
    line-height: 1;
}

.current-box {
    background: #f2494a;
    color: #fff;
    width: 150px;
    padding: 18px 12px;
    border-radius: 12px;
    box-shadow: 0 8px 20px rgba(242, 73, 74, 0.35);
}

.current-label {
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    opacity: 0.9;
    margin-bottom: 6px;
}

.current-score {
    font-size: 2.2rem;
    font-weight: 700;
}

/* Dice area in the middle */
.dice-area {
