'use strict';

const WINNING_SCORE = 100;

const scores = [0, 0];        // total scores for players 1 and 2
let currentScore = 0;         // points accumulated in current round
let activePlayer = 0;         // 0 = Player 1, 1 = Player 2
let playing = true;

const diceEl = document.getElementById('dice');
const messageEl = document.getElementById('message');
const btnNew = document.getElementById('btn-new');
const btnRoll = document.getElementById('btn-roll');
const btnHold = document.getElementById('btn-hold');

const panels = [
    document.getElementById('player-0-panel'),
    document.getElementById('player-1-panel'),
];

const scoreEls = [
    document.getElementById('player-0-score'),
    document.getElementById('player-1-score'),
];

const currentEls = [
    document.getElementById('player-0-current'),
    document.getElementById('player-1-current'),
];

function updateUI() {
    scoreEls[0].textContent = scores[0];
    scoreEls[1].textContent = scores[1];
    currentEls[activePlayer].textContent = currentScore;
    panels[activePlayer].classList.add('active');
    panels[1 - activePlayer].classList.remove('active');
}

function switchPlayer() {
    currentScore = 0;
    currentEls[activePlayer].textContent = 0;
    activePlayer = 1 - activePlayer;
    currentEls[activePlayer].textContent = 0;
    updateUI();
}

function rollDice() {
    if (!playing) return;

    const roll = Math.floor(Math.random() * 6) + 1;

    diceEl.src = `dice-${roll}.png`;
    diceEl.classList.remove('hidden', 'rolling');
    void diceEl.offsetWidth;
    diceEl.classList.add('rolling');

    if (roll === 1) {
        currentScore = 0;
        currentEls[activePlayer].textContent = 0;
        messageEl.textContent = `You rolled a 1! Turn passes to Player ${activePlayer + 1 === 1 ? 1 : 2}.`;
        switchPlayer();
        return;
    }

    currentScore += roll;
    currentEls[activePlayer].textContent = currentScore;
    messageEl.textContent = '';
}

function holdTurn() {
    if (!playing || currentScore === 0) return;

    scores[activePlayer] += currentScore;
    scoreEls[activePlayer].textContent = scores[activePlayer];
    messageEl.textContent = '';

    if (scores[activePlayer] >= WINNING_SCORE) {
        playing = false;
        panels[activePlayer].classList.add('winner-anim');
        messageEl.textContent = `🎉 Player ${activePlayer + 1} wins the game!`;
        diceEl.classList.add('hidden');
        btnRoll.disabled = true;
        btnHold.disabled = true;
        return;
    }

    switchPlayer();
}

function newGame() {
    scores[0] = 0;
    scores[1] = 0;
    currentScore = 0;
    activePlayer = 0;
    playing = true;

    scoreEls[0].textContent = 0;
    scoreEls[1].textContent = 0;
    currentEls[0].textContent = 0;
    currentEls[1].textContent = 0;
    messageEl.textContent = '';

    panels[0].classList.remove('winner-anim');
    panels[1].classList.remove('winner-anim');
    diceEl.classList.add('hidden');
    btnRoll.disabled = false;
    btnHold.disabled = false;
    updateUI();
}

btnRoll.addEventListener('click', rollDice);
btnHold.addEventListener('click', holdTurn);
btnNew.addEventListener('click', newGame);

updateUI();

const fs = require('fs');
const zlib = require('zlib');

function decodePixels(file) {
  const buf = fs.readFileSync(file);
  // find IDAT
  let off = 8, idat = [];
  while (off < buf.length) {
    const len = buf.readUInt32BE(off);
    const type = buf.toString('ascii', off + 4, off + 8);
    if (type === 'IDAT') idat.push(buf.slice(off + 8, off + 8 + len));
    off += 12 + len;
  }
  const raw = zlib.inflateSync(Buffer.concat(idat));
  const W = 200, H = 200;
  const px = (x, y) => {
    const i = raw[0] + y * (1 + W * 4) + x * 4;
    return [raw[1 + i - 1], raw[2 + i - 1], raw[3 + i - 1], raw[4 + i - 1]];
  };
  return px;
}

