html,
body {
    height: 100%;
    width: 100%;
    padding: 0;
    margin: 0;
}

.wrapper {
    background: #1c1c1c;
    color: white;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
}

.title {
    margin: 0 0 30px 0;
    font-family: sans-serif;
    letter-spacing: 2px;
}

.buttons {
    display: flex;
    gap: 20px;
    margin-bottom: 20px;
}

.rpsButton {
    height: 100px;
    width: 100px;
    font-size: 48px;
    border-radius: 30px;
    cursor: pointer;
    border: 2px solid #444;
    background: #2a2a2a;
    transition: transform 0.15s ease, border-color 0.15s ease;
}

.rpsButton:hover {
    transform: scale(1.1);
    border-color: white;
}

.rpsButton:disabled {
    opacity: 0.4;
    cursor: not-allowed;
    transform: none;
}

.resultContainer {
    font-size: 2rem;
    text-align: center;
    margin-top: 20px;
    font-family: sans-serif;
}

#player-score {
    font-size: 3rem;
    font-weight: bold;
    margin-bottom: 10px;
}

#hands {
    font-size: 1.5rem;
    margin-bottom: 10px;
}

#result {
    font-size: 2rem;
    margin-bottom: 20px;
}

#endGameButton {
    height: 50px;
    width: 50px;
    font-size: 24px;
    border-radius: 50%;
    cursor: pointer;
    border: 2px solid #444;
    background: #2a2a2a;
}

#endGameButton:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

let totalScore = { computerScore: 0, playerScore: 0 };

function getComputerChoice() {
    const rpsChoices = ["Rock", "Paper", "Scissors"];
    const randomNumber = Math.floor(Math.random() * 3);
    return rpsChoices[randomNumber];
}

function getResult(playerChoice, computerChoice) {
    let score;

    if (playerChoice === computerChoice) {
        score = 0;
    } else if (playerChoice === "Rock" && computerChoice === "Scissors") {
        score = 1;
    } else if (playerChoice === "Paper" && computerChoice === "Rock") {
        score = 1;
    } else if (playerChoice === "Scissors" && computerChoice === "Paper") {
        score = 1;
    } else {
        score = -1;
    }

    return score;
}

function showResult(score, playerChoice, computerChoice) {
    const resultDiv = document.getElementById("result");
    const handsDiv = document.getElementById("hands");
    const playerScoreDiv = document.getElementById("player-score");

    handsDiv.innerText = `${playerChoice} VS ${computerChoice}`;

    if (score === 1) {
        resultDiv.innerText = "You Win";
        resultDiv.style.color = "#2ecc71";
    } else if (score === -1) {
        resultDiv.innerText = "You Lose";
        resultDiv.style.color = "#e74c3c";
    } else {
        resultDiv.innerText = "That's a Tie";
        resultDiv.style.color = "#f1c40f";
    }

    playerScoreDiv.innerText = totalScore.playerScore;
}

function onClickRPS(playerChoice) {
    const computerChoice = getComputerChoice();
    const score = getResult(playerChoice, computerChoice);

    totalScore.playerScore += score;
    totalScore.computerScore -= score;

    showResult(score, playerChoice, computerChoice);
}

function endGame() {
    totalScore = { computerScore: 0, playerScore: 0 };

    document.getElementById("result").innerText = "";
    document.getElementById("hands").innerText = "";
    document.getElementById("player-score").innerText = "";

    const buttons = document.querySelectorAll(".rpsButton");
    buttons.forEach((button) => (button.disabled = true));

    document.getElementById("endGameButton").disabled = true;
}

document.querySelectorAll(".rpsButton").forEach((button) => {
    button.addEventListener("click", () => onClickRPS(button.value));
});

document.getElementById("endGameButton").addEventListener("click", endGame);

const http = require('http');
const fs = require('fs');

const CDP_PIPE = process.env.CDP_PIPE || '/tmp/cdp_pipe';
const OUT = process.env.OUT || '/tmp/rps';

async function getVersion() {
  return new Promise((resolve, reject) => {
    http.get('http://127.0.0.1:9222/json/version', (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => resolve(JSON.parse(d)));
    }).on('error', reject);
  });
}

async function newTab() {
  return new Promise((resolve, reject) => {
    http.put('http://127.0.0.1:9222/json/new?http://127.0.0.1:9222', (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => resolve(JSON.parse(d)));
    }).on('error', reject);
  });
}

function main() {
  return new Promise(async (resolveMain, rejectMain) => {
    let ws;
    const pending = new Map();
    let msgId = 0;

    function send(method, params) {
      return new Promise((resolve, reject) => {
        const id = ++msgId;
        pending.set(id, { resolve, reject });
        ws.send(JSON.stringify({ id, method, params }));
      });
    }

    const tab = await newTab();
    ws = new WebSocket('ws://127.0.0.1:9222/devtools/page/' + tab.id);
    await new Promise((res, rej) => {
      ws.onopen = res;
      ws.onerror = rej;
    });

    ws.onmessage = (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id && pending.has(msg.id)) {
        const p = pending.get(msg.id);
        pending.delete(msg.id);
        if (msg.error) p.reject(new Error(JSON.stringify(msg.error)));
        else p.resolve(msg.result);
      }
    };

    const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

    try {
      await send('Page.enable');
      await send('Runtime.enable');

      const url = 'file:///repo/Rock-Paper-Scissors/index.html';
      await send('Page.navigate', { url });
      await sleep(800);

      const evalJs = async (expr) => {
        const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true });
        if (r.exceptionDetails) throw new Error('JS eval failed: ' + JSON.stringify(r.exceptionDetails));
        return r.result.value;
      };

      const checks = [];

      // 1. Initial state
      checks.push(['initial score', (await evalJs(`document.getElementById('player-score').innerText`)) === '0']);
      checks.push(['3 rps buttons', (await evalJs(`document.querySelectorAll('.rpsButton').length`)) === 3]);
      checks.push(['button values', await evalJs(`[...document.querySelectorAll('.rpsButton')].map(b => b.value).join(',')`)]);
      checks.push(['end button exists', await evalJs(`!!document.getElementById('endGameButton')`)]);

      // 2. Logic units
      const logic = await evalJs(`(() => {
        const rpsChoices = ['Rock','Paper','Scissors'];
        const results = [];
        for (const p of rpsChoices) {
          for (const c of rpsChoices) {
            const s = getResult(p, c);
            const expected = p === c ? 0 : (p === 'Rock' && c === 'Scissors') || (p === 'Paper' && c === 'Rock') || (p === 'Scissors' && c === 'Paper') ? 1 : -1;
            if (s !== expected) results.push(p + ' VS ' + c + ' => ' + s);
          }
        }
        const compValid = (() => { for (let i=0;i<200;i++){ const c = getComputerChoice(); if (!rpsChoices.includes(c)) return false;} return true; })();
        return { mismatches: results, compValid };
      })()`);
      checks.push(['getResult all 9 combos correct', logic.mismatches.length === 0]);
      checks.push(['getComputerChoice valid', logic.compValid]);

      // 3. Interaction: force deterministic random, click Rock
      const clickResult = await evalJs(`(async () => {
        Math.random = () => 0; // Rock
        document.querySelector('.rpsButton[value="Rock"]').click();
        await new Promise(r => setTimeout(r, 50));
        const hands = document.getElementById('hands').innerText;
        const res = document.getElementById('result').innerText;
        const score = document.getElementById('player-score').innerText;
        return { hands, res, score };
      })()`);
      // Rock vs Rock => tie (score -0 -> 0)
      checks.push(['click hand text', clickResult.hands === 'Rock VS Rock']);
      checks.push(['tie result msg', clickResult.res === "That's a Tie"]);
      checks.push(['score remains 0 on tie', clickResult.score === '0']);

      // Win: Rock vs Scissors
      const win = await evalJs(`(async () => {
        Math.random = () => 0.99; // Scissors
        document.querySelector('.rpsButton[value="Rock"]').click();
        await new Promise(r => setTimeout(r, 50));
        return { res: document.getElementById('result').innerText, score: document.getElementById('player-score').innerText };
      })()`);
      checks.push(['win msg', win.res === 'You Win']);
      checks.push(['score increments', win.score === '1']);

      // Lose: Paper; computer Rock via random 0.1
      const lose = await evalJs(`(async () => {
        Math.random = () => 0.1; // Rock
        document.querySelector('.rpsButton[value="Paper"]').click();
        await new Promise(r => setTimeout(r, 50));
        return { res: document.getElementById('result').innerText, score: document.getElementById('player-score').innerText };
      })()`);
      checks.push(['lose msg', lose.res === 'You Lose']);
      checks.push(['score decrements', lose.score === '0']);

      // 4. End game: set a score, click end
      const endGame = await evalJs(`(async () => {
        totalScore.playerScore = 5;
        totalScore.computerScore = 2;
        document.getElementById('player-score').innerText = '5';
        document.getElementById('endGameButton').click();
        await new Promise(r => setTimeout(r, 50));
        const disabled = [...document.querySelectorAll('.rpsButton')].every(b => b.disabled);
        const endDisabled = document.getElementById('endGameButton').disabled;
        const scoreReset = document.getElementById('player-score').innerText === '' && totalScore.playerScore === 0 && totalScore.computerScore === 0;
        return { disabled, endDisabled, scoreReset };
      })()`);
      checks.push(['end disables rps buttons', endGame.disabled]);
      checks.push(['end disables itself', endGame.endDisabled]);
      checks.push(['end resets scores', endGame.scoreReset]);

      // 5. Screenshot: reset all, play one round for a good screenshot, then capture
      await evalJs(`(async () => {
        document.getElementById('player-score').innerText = '3';
        document.getElementById('hands').innerText = 'Rock VS Rock';
        document.getElementById('result').innerText = "That's a Tie";
      })()`);
      await sleep(200);

      const shot = await send('Page.captureScreenshot', { format: 'png', fromSurface: true });
      fs.writeFileSync(OUT + '_tab.png', Buffer.from(shot.data, 'base64'));

      // print results
      let failed = 0;
      for (const [name, ok] of checks) {
        if (!ok) failed++;
        console.log((ok ? 'PASS' : 'FAIL') + ' - ' + name);
      }
      console.log('SUMMARY ' + (checks.length - failed) + '/' + checks.length);
      resolveMain();
    } catch (e) {
      rejectMain(e);
    } finally {
      try { ws.close(); } catch (e) {}
    }
  });
}

main().then(() => process.exit(0)).catch((e) => { console.error('ERROR', e); process.exit(1); });

