const http = require('http');
const fs = require('fs');

function get(p) {
  return new Promise((res) => {
    const req = http.get({ host: '127.0.0.1', port: 9222, path: p }, (r) => {
      let d = '';
      r.on('data', (c) => (d += c));
      r.on('end', () => res(d));
    });
    req.on('error', (e) => res('ERR:' + e.message));
  });
}

async function main() {
  const list = JSON.parse(await get('/json'));
  const tab = list.find((t) => t.type === 'page');
  const ws = new WebSocket(tab.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  let id = 0; const pending = new Map();
  ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m.result); pending.delete(m.id); } };
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expr) => { const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true }); return r.result ? r.result.value : r; };

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: 'file:///repo/Rock-Paper-Scissors/index.html' });
  await new Promise((r) => setTimeout(r, 800));

  const viewport = await ev(`({ w: innerWidth, h: innerHeight })`);
  console.log('viewport', viewport);

  // Play three rounds to accumulate a score: win, tie, win -> playerScore 2
  const state = await ev(`(() => {
    let out = [];
    Math.random = () => 0.99; // Scissors
    document.querySelector('.rpsButton[value="Rock"]').click(); // win
    out.push(document.getElementById('hands').innerText + '|' + document.getElementById('result').innerText + '|' + document.getElementById('player-score').innerText);
