import json, subprocess, time, os, sys
from websocket import create_connection

CHROME = "/usr/bin/chromium"
URL = "file:///repo/Javascript Documentation/index.html"

def launch(port, width, height):
    p = subprocess.Popen([
        CHROME, "--headless", "--disable-gpu", "--no-sandbox",
        "--no-first-run", f"--remote-debugging-port={port}",
        f"--window-size={width},{height}", URL
    ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    for _ in range(60):
        try:
            c = create_connection(f"ws://127.0.0.1:{port}/devtools/page/1", timeout=1)
            c.close()
            break
        except Exception:
            time.sleep(0.2)
    else:
        raise RuntimeError("devtools not up")
    return p

def get_ws(port):
    import urllib.request
    for _ in range(40):
        try:
            with urllib.request.urlopen(f"http://127.0.0.1:{port}/json/list") as r:
                pages = json.load(r)
            for pg in pages:
                if pg.get("type") == "page":
                    return pg["webSocketDebuggerUrl"]
        except Exception:
            pass
        time.sleep(0.2)
    raise RuntimeError("no page ws")

def cdp(ws, method, params=None):
    global _id
    _id += 1
    ws.send(json.dumps({"id": _id, "method": method, "params": params or {}}))
    while True:
        msg = json.loads(ws.recv())
        if msg.get("id") == _id:
            if "error" in msg:
                raise RuntimeError(msg["error"])
            return msg.get("result", {})

def evaljs(ws, expr):
    r = cdp(ws, "Runtime.evaluate", {"expression": expr, "returnByValue": True})
    return r.get("result", {}).get("value")

def run(port, width, height, label):
    _id[0] = 0
    proc = launch(port, width, height)
    try:
        ws_url = get_ws(port)
        ws = create_connection(ws_url, timeout=20)
        cdp(ws, "Page.enable")
        cdp(ws, "Runtime.enable")
        time.sleep(1.0)
        results = {}
        results["title"] = evaljs(ws, "document.title")
        results["nav_count"] = evaljs(ws, "document.querySelectorAll('#navbar .nav-link').length")
        results["nav_links_match"] = evaljs(ws, """
          (function(){
            var links = Array.from(document.querySelectorAll('#navbar .nav-link')).map(a => a.hash.slice(1));
            var secs = Array.from(document.querySelectorAll('.main-section')).map(s => s.id);
            return links.length===secs.length && links.every(x=>secs.includes(x));
          })()
        """)
        results["has_media_815"] = evaljs(ws, """
          Array.from(document.styleSheets[0].cssRules)
            .some(r => r.type === CSSRule.MEDIA_RULE && r.media.mediaText.indexOf("815") !== -1)
        """)
        results["nav_position"] = evaljs(ws, "getComputedStyle(document.getElementById('navbar')).position")
        results["nav_width"] = evaljs(ws, "document.getElementById('navbar').getBoundingClientRect().width")
        results["nav_section_count"] = evaljs(ws, "document.querySelectorAll('section.main-section').length")
        results["body_scrollwidth_lt_viewport"] = evaljs(ws, "document.documentElement.scrollWidth <= window.innerWidth")
        results["doc_scrollwidth"] = evaljs(ws, "document.documentElement.scrollWidth")
        results["viewport"] = evaljs(ws, "window.innerWidth")
        results["first_section_header_visible"] = evaljs(ws, """
          (function(){
            var h = document.querySelector('.main-section header');
            var r = h.getBoundingClientRect();
            return r.width > 0 && r.height > 0;
          })()
        """)
        # click a nav link and confirm anchor navigates
        evaljs(ws, "document.querySelector('.nav-link').click()")
        time.sleep(0.5)
        results["after_click_hash"] = evaljs(ws, "location.hash")
        ws.close()
        print(f"=== {label} ({width}x{height}) ===")
        for k, v in results.items():
            print(f"  {k}: {v}")
    finally:
        proc.terminate()

if __name__ == "__main__":
