.presence-toggle {
  display: flex;
  gap: 6px;
}

.presence-btn {
  padding: 6px 14px;
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 8px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--muted);
}

.presence-btn.present.active {
  background: var(--success);
  border-color: var(--success);
  color: #fff;
}

.presence-btn.absent.active {
  background: var(--admin);
  border-color: var(--admin);
  color: #fff;
}

/* ---------- Exam ---------- */

.exam-question {
  background: #f8fafc;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px;
  margin-bottom: 12px;
}

.exam-question .q-text {
  font-weight: 600;
  margin-bottom: 10px;
}

.option-label {
  display: block;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  margin-bottom: 6px;
  background: #fff;
  cursor: pointer;
  font-size: 0.9rem;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.option-label:hover {
  border-color: var(--student);
}

.option-label input {
  margin-right: 8px;
  accent-color: var(--student);
}

.option-label.selected {
  border-color: var(--student);
  background: rgba(37, 99, 235, 0.06);
}

.result-banner {
  border-radius: 10px;
  padding: 14px;
  margin-bottom: 14px;
  font-weight: 600;
  font-size: 0.95rem;
}

.result-pass {
  background: #dcfce7;
  color: #166534;
}

.result-fail {
  background: #fee2e2;
  color: #991b1b;
}

.alert {
  padding: 12px 14px;
  border-radius: 10px;
  font-size: 0.88rem;
  margin-bottom: 14px;
}

.alert-info {
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
}

.alert-success {
  background: #dcfce7;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.meter {
  height: 8px;
  background: #e5e7eb;
  border-radius: 999px;
  overflow: hidden;
  margin-top: 8px;
}

.meter-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--student), #60a5fa);
}

/* ---------- Toast ---------- */

.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--sidebar);
  color: #fff;
  padding: 12px 20px;
  border-radius: 10px;
  font-size: 0.88rem;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 100;
}

.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ---------- Empty state ---------- */

.empty-state {
  text-align: center;
  padding: 36px 20px;
  color: var(--muted);
}

.empty-state .empty-icon {
  font-size: 2.4rem;
  margin-bottom: 10px;
}

/* phrase helper */
.pair-list {
  list-style: none;
}

.pair-list li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
  border-bottom: 1px dashed var(--border);
  font-size: 0.9rem;
}

.pair-list li:last-child {
  border-bottom: none;
}

.pair-list .k {
  color: var(--muted);
}

.pair-list .v {
  font-weight: 600;
  text-align: right;
}

.pill {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 0.74rem;
  font-weight: 700;
}

.pill-ok {
  background: #dcfce7;
  color: #166534;
}

.pill-pending {
  background: #fef3c7;
  color: #92400e;
}

.pill-muted {
  background: #e2e8f0;
  color: #475569;
}

/* ---------- Responsive ---------- */

@media (max-width: 768px) {
  .sidebar {
    transform: translateX(-100%);
  }

  .sidebar.open {
    transform: translateX(0);
  }

  .menu-toggle {
    display: block;
  }

  .main {
    margin-left: 0;
  }

  .topbar {
    padding: 0 16px;
  }

  .content {
    padding: 18px 16px 32px;
  }

  .cards-grid {
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  }

  .overlay {
    position: fixed;
    inset: 0;
    background: rgba(15, 23, 42, 0.45);
    z-index: 35;
  }
}

