    if (p >= 90) return { grade: "A+", p: p };
    if (p >= 80) return { grade: "A", p: p };
    if (p >= 70) return { grade: "B+", p: p };
    if (p >= 60) return { grade: "B", p: p };
    if (p >= 50) return { grade: "C", p: p };
    return { grade: "F", p: p };
