    var marks = getMarksForStudent(user.id);
    var avg = marks.length
      ? Math.round(marks.reduce(function (acc, m) { return acc + (m.score / m.total) * 100; }, 0) / marks.length)
      : 0;
    var stats = [
      { icon: "📚", value: marks.length, label: "Subjects graded" },
      { icon: "🎯", value: avg + "%", label: "Average score" },
      { icon: "🏆", value: topSubject(marks), label: "Best subject" }
    ];
    var rows = marks.length ? marks.map(function (m) {
      var g = gradeOf(m.score, m.total);
      var sub = getSubject(m.subjectCode);
      return "<tr><td>" + escapeHtml(sub ? sub.name : m.subjectCode) + "</td><td>" + escapeHtml(m.subjectCode) +
        "</td><td>" + m.score + " / " + m.total + "</td><td>" + g.p.toFixed(1) + "%</td><td><span class='pill " +
        (g.grade === "F" ? "pill-pending" : "pill-ok") + "'>" + g.grade + "</span></td></tr>";
    }).join("") : "";
    return statCards(stats) +
      '<div class="card"><h3>📊 My Marks</h3>' +
      (marks.length
        ? '<div class="table-wrap"><table class="data-table"><thead><tr><th>Subject</th><th>Code</th><th>Score</th><th>Percentage</th><th>Grade</th></tr></thead><tbody>' + rows + "</tbody></table></div>"
        : '<div class="empty-state"><div class="empty-icon">📭</div><p>No marks posted yet.</p></div>') +
      "</div>";
  };

  function topSubject(marks) {
    if (!marks.length) return "—";
    var best = marks.slice().sort(function (a, b) {
      return (b.score / b.total) - (a.score / a.total);
    })[0];
    var sub = getSubject(best.subjectCode);
    return escapeHtml(sub ? sub.code : "—");
  }

