  function renderExam(examId) {
    var exam = getExam(examId);
    var user = findUser(session.userId);
    if (!exam) return;
    var questions = exam.questions.map(function (q, qi) {
      var opts = q.options.map(function (o, oi) {
        return '<label class="option-label"><input type="radio" name="q' + qi + '" value="' + oi + '"> ' + escapeHtml(o) + "</label>";
      }).join("");
      return '<div class="exam-question"><div class="q-text">Q' + (qi + 1) + ". " + escapeHtml(q.q) + "</div>" + opts + "</div>";
    }).join("");
    el("main-content").innerHTML =
      '<div class="card"><h3>📝 ' + escapeHtml(exam.title) + "</h3>" +
      '<p class="card-subtitle">Answer all questions and click Submit.</p>' +
      '<form id="exam-form">' + questions +
      '<button type="submit" class="btn btn-primary">Submit exam</button>' +
      "</form></div>";
    el("exam-form").addEventListener("submit", function (e) {
      e.preventDefault();
      var form = e.target;
      var score = 0;
      for (var qi = 0; qi < exam.questions.length; qi++) {
        var sel = form.querySelector('input[name="q' + qi + '"]:checked');
        if (sel && parseInt(sel.value, 10) === exam.questions[qi].answer) {
          score++;
        }
      }
      var existing = getResult(exam.id, user.id);
      if (existing) {
        existing.score = score;
        existing.total = exam.totalMarks;
        existing.takenAt = nowDate();
      } else {
        DB.examResults.push({
          id: uid("er"),
          examId: exam.id,
          studentId: user.id,
          score: score,
          total: exam.totalMarks,
          takenAt: nowDate()
        });
      }
      saveDB();
      goTo("exams");
      showToast("Exam submitted. You scored " + score + " / " + exam.totalMarks);
    });
  }

