    var days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"].map(function (d) {
      return "<option>" + d + "</option>";
    }).join("");
    var html = '<div class="card"><h3>🗓️ Manage Timetable</h3>' +
      '<p class="card-subtitle">Schedule a subject into a day and period. Add to make the slot available to students and teachers.</p>' +
