      '<div class="field"><label>Subject</label><select id="tt-new-subject">' + subs + "</select></div>" +
      '<div class="field"><label>Room</label><input type="text" id="tt-new-room" placeholder="e.g. A-101"></div>' +
      "</div>" +
      '<button type="button" class="btn btn-admin" id="tt-add">Add slot</button></div>' +
      '<div class="card"><h3>Current timetable</h3><div class="table-wrap"><table class="data-table"><thead>' +
      "<tr><th>Day</th><th>Period</th><th>Time</th><th>Subject</th><th>Room</th><th></th></tr></thead><tbody>" +
      DB.timetable.map(function (t) {
        var sub = getSubject(t.subjectCode);
        return "<tr><td>" + escapeHtml(t.day) + "</td><td>" + t.period + "</td><td>" + escapeHtml(t.time) +
          "</td><td>" + escapeHtml(sub ? sub.name : t.subjectCode) + "</td><td>" + escapeHtml(t.room) + "</td>" +
          "<td><button type='button' class='btn btn-danger btn-sm' data-remove='tt' data-id='" + t.id + "'>Remove</button></td></tr>";
      }).join("") +
      "</tbody></table></div></div>";
    return html;
  };

  function bindAdminTimetable(page) {
    var addBtn = el("tt-add");
    if (addBtn) {
      addBtn.addEventListener("click", function () {
        var day = el("tt-new-day").value;
        var period = parseInt(el("tt-new-period").value, 10);
        var code = el("tt-new-subject").value;
        var room = el("tt-new-room").value.trim() || "—";
        var time = timeForPeriod(period);
        var dup = DB.timetable.some(function (t) { return t.day === day && t.period === period; });
        if (dup) {
          showToast("Period already scheduled for that day");
          return;
        }
        DB.timetable.push({ id: uid("t"), day: day, period: period, time: time, subjectCode: code, room: room });
        saveDB();
        showToast("Timetable slot added");
        goTo("timetable");
      });
    }
    page.querySelectorAll("[data-remove='tt']").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var id = this.getAttribute("data-id");
        DB.timetable = DB.timetable.filter(function (t) { return t.id !== id; });
        saveDB();
        showToast("Slot removed");
        goTo("timetable");
      });
    });
  }

  function timeForPeriod(p) {
    var map = { 1: "09:00 - 10:00", 2: "10:00 - 11:00", 3: "11:00 - 12:00", 4: "12:00 - 13:00" };
    return map[p] || "09:00 - 10:00";
  }

  function subjectsForSelect(studentId) {
    var codes = getSubjectsForStudent(studentId).map(function (s) { return s.code; });
    return codes.length ? codes : DB.subjects.map(function (s) { return s.code; });
  }

  function formatBytes(n) {
    if (!n) return "0 B";
    var units = ["B", "KB", "MB", "GB"];
    var i = 0;
    var v = n;
    while (v >= 1024 && i < units.length - 1) {
      v /= 1024;
      i++;
    }
    return v.toFixed(v >= 10 || i === 0 ? 0 : 1) + " " + units[i];
  }

  /* ---------- Mobile nav ---------- */

  function openMobileNav() {
    el("sidebar").classList.add("open");
    var overlay = document.createElement("div");
    overlay.className = "overlay";
    overlay.id = "nav-overlay";
    overlay.addEventListener("click", closeMobileNav);
    document.body.appendChild(overlay);
  }

  function closeMobileNav() {
    el("sidebar").classList.remove("open");
    var overlay = el("nav-overlay");
    if (overlay) overlay.parentNode.removeChild(overlay);
  }

  function toggleMobileNav() {
    if (el("sidebar").classList.contains("open")) {
      closeMobileNav();
    } else {
      openMobileNav();
    }
  }

  /* ---------- Init ---------- */

  function init() {
    DB = loadDB();

    var loginForm = el("login-form");
    loginForm.addEventListener("submit", function (e) {
      e.preventDefault();
      var activeRole = document.querySelector(".role-btn.active");
      var role = activeRole ? activeRole.getAttribute("data-role") : ROLES.student;
      var username = el("username").value;
      var password = el("password").value;
      var res = login(username, password, role);
      if (res.ok) {
        showScreen("app");
      } else {
        showToast(res.message);
      }
    });

    el("role-selector").addEventListener("click", function (e) {
      var btn = e.target.closest(".role-btn");
      if (!btn) return;
      document.querySelectorAll(".role-btn").forEach(function (b) { b.classList.remove("active"); });
      btn.classList.add("active");
    });

    el("logout-btn").addEventListener("click", function () {
      logout();
      showScreen("login");
      el("login-form").reset();
    });

    el("menu-toggle").addEventListener("click", toggleMobileNav);

    el("nav-menu").addEventListener("click", function (e) {
      var item = e.target.closest(".nav-item");
      if (!item) return;
      goTo(item.getAttribute("data-tab"));
    });

    if (typeof NodeList.prototype.forEach === "undefined") {
      NodeList.prototype.forEach = function (cb) {
        for (var i = 0; i < this.length; i++) cb(this[i], i, this);
      };
    }

    session = loadSession();
    if (session) {
      showScreen("app");
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

