'use strict';
const http = require('http');
const { spawn } = require('child_process');

const PORT = 9223;
const FILE = 'file:///repo/College%20ERP%20System/index.html';

function getJSON(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { reject(e); }
      });
    }).on('error', reject);
  });
}

class CDP {
  constructor(wsurl) {
    this.ws = new WebSocket(wsurl);
    this.id = 0;
    this.pending = new Map();
    this.events = [];
  }
  connect() {
    return new Promise((resolve, reject) => {
      this.ws.onopen = () => resolve();
      this.ws.onerror = (e) => reject(new Error('ws error'));
      this.ws.onmessage = (ev) => {
        const msg = JSON.parse(ev.data);
        if (msg.id && this.pending.has(msg.id)) {
          const { resolve, reject } = this.pending.get(msg.id);
          this.pending.delete(msg.id);
          if (msg.error) reject(new Error(JSON.stringify(msg.error)));
          else resolve(msg.result);
        } else {
          this.events.push(msg);
        }
      };
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => this.pending.set(id, { resolve, reject }));
  }
}

async function main() {
  const chrome = spawn('chromium', [
    '--headless=new',
    '--no-sandbox',
    '--disable-dev-shm-usage',
    '--disable-gpu',
    `--remote-debugging-port=${PORT}`,
    '--window-size=1280,900',
    FILE
  ], { stdio: 'ignore' });

  let target;
  for (let i = 0; i < 40; i++) {
    try {
      const list = await getJSON(`http://127.0.0.1:${PORT}/json/list`);
      const page = list.find((t) => t.type === 'page' && t.url.startsWith('file:'));
      if (page) { target = page; break; }
    } catch (e) { /* retry */ }
    await new Promise((r) => setTimeout(r, 250));
  }
  if (!target) { throw new Error('No page target'); }

  const cdp = new CDP(target.webSocketDebuggerUrl);
  await cdp.connect();
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');

  async function waitForLoad() {
    await cdp.send('Page.navigate', { url: FILE });
    await new Promise((r) => setTimeout(r, 1500));
  }

  async function evalJS(expr) {
    const res = await cdp.send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
    if (res.exceptionDetails) throw new Error(JSON.stringify(res.exceptionDetails));
    return res.result.value;
  }

  const results = [];
  function check(name, cond) {
    results.push({ name, pass: !!cond });
  }

  await waitForLoad();

  // Check login screen present
  check('login screen visible', await evalJS("document.getElementById('login-screen').classList.contains('hidden') === false"));
  check('app screen hidden', await evalJS("document.getElementById('app-screen').classList.contains('hidden') === true"));
  check('login form exists', await evalJS("!!document.getElementById('login-form')"));
  check('role selector has 3 buttons', await evalJS("document.querySelectorAll('.role-btn').length === 3"));

  async function login(username, password, role) {
    await evalJS(`
      document.querySelectorAll('.role-btn').forEach(b => b.classList.remove('active'));
      const btn = Array.from(document.querySelectorAll('.role-btn')).find(b => b.getAttribute('data-role') === '${role}');
      btn.classList.add('active');
      document.getElementById('username').value = '${username}';
      document.getElementById('password').value = '${password}';
      document.getElementById('login-form').dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
    `);
    await new Promise((r) => setTimeout(r, 300));
    return evalJS("!document.getElementById('app-screen').classList.contains('hidden')");
  }

  // Bad login
  const badLogin = await login('student1', 'wrongpass', 'student');
  check('bad password rejected', badLogin === false);

  // Wrong role
  const wrongRole = await login('student1', 'student123', 'teacher');
  check('wrong role rejected', wrongRole === false);

  // Student login
  const studentOk = await login('student1', 'student123', 'student');
  check('student login works', studentOk === true);
  check('student nav has 5 items', await evalJS("document.querySelectorAll('.nav-item').length === 5"));
  check('student page title = My Marks', await evalJS("document.getElementById('page-title').textContent === 'My Marks'"));
  check('marks table has 3 rows', await evalJS("document.querySelectorAll('.data-table tbody tr').length === 3"));
  check('stat cards shown', await evalJS("document.querySelectorAll('.stat-card').length === 3"));

  // Student: assignments tab
  await evalJS("goTo('assignments')");
