'use strict';
const http = require('http');
const { spawn } = require('child_process');
const fs = require('fs');

const PORT = 9227;
const FILE = 'file:///repo/College%20ERP%20System/index.html';

function getJSON(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { reject(e); }
      });
    }).on('error', reject);
  });
}

class CDP {
  constructor(wsurl) {
    this.ws = new WebSocket(wsurl);
    this.id = 0;
    this.pending = new Map();
  }
  connect() {
    return new Promise((resolve, reject) => {
      this.ws.onopen = () => resolve();
      this.ws.onerror = () => reject(new Error('ws error'));
      this.ws.onmessage = (ev) => {
        const msg = JSON.parse(ev.data);
        if (msg.id && this.pending.has(msg.id)) {
          const { resolve, reject } = this.pending.get(msg.id);
          this.pending.delete(msg.id);
          if (msg.error) reject(new Error(JSON.stringify(msg.error)));
          else resolve(msg.result);
        }
      };
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => this.pending.set(id, { resolve, reject }));
  }
}

const results = [];
function check(name, cond) {
  results.push({ name, pass: !!cond });
}

async function main() {
  const chrome = spawn('chromium', [
    '--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu',
    `--remote-debugging-port=${PORT}`, '--window-size=1280,900', FILE
  ], { stdio: 'ignore' });

  let target;
  for (let i = 0; i < 40; i++) {
    try {
      const list = await getJSON(`http://127.0.0.1:${PORT}/json/list`);
      const page = list.find((t) => t.type === 'page' && t.url.startsWith('file:'));
      if (page) { target = page; break; }
    } catch (e) { /* retry */ }
    await new Promise((r) => setTimeout(r, 250));
  }
  if (!target) throw new Error('No page target');

  const cdp = new CDP(target.webSocketDebuggerUrl);
  await cdp.connect();
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  async function run(expr) {
    const res = await cdp.send('Runtime.evaluate', {
      expression: '(function(){ ' + expr + ' })()',
      returnByValue: true,
      awaitPromise: true
    });
    if (res.exceptionDetails) {
      throw new Error('EVAL ERR: ' + JSON.stringify(res.exceptionDetails));
    }
    return res.result.value;
  }

  async function value(expr) {
    const res = await cdp.send('Runtime.evaluate', {
      expression: '(function(){ return (' + expr + '); })()',
      returnByValue: true,
      awaitPromise: true
    });
    if (res.exceptionDetails) {
      throw new Error('VALUE ERR: ' + JSON.stringify(res.exceptionDetails));
    }
    return res.result.value;
  }

  await cdp.send('Page.navigate', { url: FILE });
  await sleep(1600);

  async function login(username, password, role) {
    await run(`
      document.querySelectorAll('.role-btn').forEach(b => b.classList.remove('active'));
      var btn = Array.from(document.querySelectorAll('.role-btn')).find(b => b.getAttribute('data-role') === '${role}');
      btn.classList.add('active');
      document.getElementById('username').value = '${username}';
      document.getElementById('password').value = '${password}';
      document.getElementById('login-form').dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
    `);
    await sleep(400);
    return value("!document.getElementById('app-screen').classList.contains('hidden')");
  }

  async function clickNav(tab) {
    await run(`
      var item = Array.from(document.querySelectorAll('.nav-item')).find(i => i.getAttribute('data-tab') === '${tab}');
      item.click();
    `);
    await sleep(250);
  }

  // ---- Login screen ----
  check('login screen visible', await value("document.getElementById('login-screen').classList.contains('hidden') === false"));
  check('app screen hidden', await value("document.getElementById('app-screen').classList.contains('hidden') === true"));
  check('login form exists', await value("!!document.getElementById('login-form')"));
  check('role selector has 3 buttons', await value("document.querySelectorAll('.role-btn').length === 3"));
  check('demo credentials shown', await value("document.querySelectorAll('.demo-table tr').length === 3"));

  // ---- Bad logins ----
  const badLogin = await login('student1', 'wrongpass', 'student');
  check('wrong password rejected', badLogin === false);

  const wrongRole = await login('student1', 'student123', 'teacher');
  check('wrong role rejected', wrongRole === false);

  // ---- Student flow ----
  const studentOk = await login('student1', 'student123', 'student');
  check('student login works', studentOk === true);
  check('student page title defaults to My Marks', await value("document.getElementById('page-title').textContent === 'My Marks'"));
  check('student nav has 5 items', await value("document.querySelectorAll('.nav-item').length === 5"));
  check('marks stat cards shown', await value("document.querySelectorAll('.stat-card').length === 3"));
  check('marks table has 3 rows', await value("document.querySelectorAll('.data-table tbody tr').length === 3"));

  await clickNav('assignments');
  check('assignments page renders', await value("document.getElementById('main-content').textContent.indexOf('Submit Assignment') !== -1"));
  check('assignment cards rendered', await value("document.querySelectorAll('.upload-btn').length + document.querySelectorAll('.alert-success').length >= 3"));

  await clickNav('exams');
  check('exams page renders', await value("document.getElementById('main-content').textContent.indexOf('Available Exams') !== -1"));
  check('start exam buttons (2)', await value("document.querySelectorAll('.start-exam').length === 2"));

  await run("document.querySelector('.start-exam').click()");
  await sleep(250);
  check('exam form rendered', await value("!!document.getElementById('exam-form')"));
  check('exam has 5 questions', await value("document.querySelectorAll('.exam-question').length === 5"));

  await run(`
    document.querySelectorAll('.exam-question').forEach(q => {
      q.querySelector('input[type=radio]').checked = true;
    });
    document.getElementById('exam-form').dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
  `);
  await sleep(400);
  check('exam submitted back to list', await value("document.getElementById('main-content').textContent.indexOf('Available Exams') !== -1"));
  check('exam result shown for student1', await value("document.getElementById('main-content').textContent.indexOf('Your score:') !== -1"));

  await clickNav('attendance');
  check('student attendance renders', await value("document.getElementById('main-content').textContent.indexOf('My Attendance') !== -1"));
  check('attendance table has rows', await value("document.querySelectorAll('.data-table tbody tr').length >= 1"));

  await clickNav('timetable');
  check('student timetable renders', await value("document.getElementById('main-content').textContent.indexOf('Timetable') !== -1"));
  check('timetable has 4 periods Monday', await value("document.querySelectorAll('.data-table tbody tr').length >= 4"));

  // ---- Logout ----
  await run("document.getElementById('logout-btn').click()");
  await sleep(250);
  check('logout returns to login', await value("!document.getElementById('login-screen').classList.contains('hidden')"));

  // ---- Teacher flow ----
  const teacherOk = await login('teacher1', 'teacher123', 'teacher');
  check('teacher login works', teacherOk === true);
  check('teacher dashboard renders', await value("document.getElementById('main-content').textContent.indexOf('My Subjects') !== -1"));
  check('teacher stat cards (4)', await value("document.querySelectorAll('.stat-card').length === 4"));

  await clickNav('evaluate');
  check('evaluate page renders', await value("!!document.getElementById('eval-assign')"));
  await run("document.getElementById('eval-load').click()");
  await sleep(300);
  check('submissions loaded', await value("document.querySelectorAll('#eval-results .eval-save').length >= 3"));

  await clickNav('postmarks');
  check('postmarks page renders', await value("!!document.getElementById('marks-subject')"));
  await run("document.getElementById('marks-load').click()");
  await sleep(300);
  check('postmarks loads students', await value("document.querySelectorAll('#marks-results .attendance-row').length >= 3"));

  await clickNav('attendance');
  check('teacher attendance renders', await value("!!document.getElementById('att-subject')"));
  await run("document.getElementById('att-load').click()");
  await sleep(300);
  check('attendance loads class', await value("document.querySelectorAll('#att-results .attendance-row').length >= 3"));
  check('presence toggles active', await value("document.querySelectorAll('#att-results .presence-btn.active').length >= 3"));

  await run("document.getElementById('logout-btn').click()");
  await sleep(250);

  // ---- Admin flow ----
  const adminOk = await login('admin', 'admin123', 'admin');
  check('admin login works', adminOk === true);
  check('admin dashboard renders', await value("document.getElementById('main-content').textContent.indexOf('Recent accounts') !== -1"));
  check('admin stat cards (4)', await value("document.querySelectorAll('.stat-card').length === 4"));

  await clickNav('users');
  check('create IDs page renders', await value("!!document.getElementById('new-username') && !!document.getElementById('create-user')"));
  check('accounts table lists all users', await value("document.querySelectorAll('.data-table tbody tr').length === 6"));
  await run(`
    document.getElementById('new-role').value = 'teacher';
    document.getElementById('new-name').value = 'Test Teacher';
    document.getElementById('new-username').value = 'tt1';
    document.getElementById('new-password').value = 'ttpass';
    document.getElementById('create-user').click();
  `);
  await sleep(400);
  check('created user shown in result box', await value("document.getElementById('new-user-result').textContent.indexOf('Test Teacher') !== -1"));

  await clickNav('subjects');
  check('subjects page renders', await value("!!document.getElementById('add-subject')"));

  await clickNav('timetable');
  check('admin timetable renders', await value("!!document.getElementById('tt-add')"));
  check('timetable rows present', await value("document.querySelectorAll('.data-table tbody tr').length >= 7"));

  // ---- Mobile responsive ----
  await cdp.send('Emulation.setDeviceMetricsOverride', { width: 414, height: 900, deviceScaleFactor: 1, mobile: true });
  await sleep(400);
  check('no horizontal overflow (414px)', await value("document.documentElement.scrollWidth <= 414"));
  check('menu toggle visible on mobile', await value("getComputedStyle(document.getElementById('menu-toggle')).display !== 'none'"));
  await run("document.getElementById('menu-toggle').click()");
  await sleep(300);
  check('mobile sidebar opens', await value("document.getElementById('sidebar').classList.contains('open')"));

  // ---- Screenshots at desktop ----
  await cdp.send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
  await cdp.send('Page.navigate', { url: FILE });
  await sleep(1500);
  let shot = await cdp.send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('/repo/College ERP System/screenshot.png', Buffer.from(shot.data, 'base64'));
  console.log('screenshot.png saved');

  await cdp.send('Page.navigate', { url: FILE });
  await sleep(1500);
  await login('student1', 'student123', 'student');
  await sleep(300);
  shot = await cdp.send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('/repo/College ERP System/screenshot-student.png', Buffer.from(shot.data, 'base64'));
  console.log('screenshot-student.png saved');

  await run("document.getElementById('logout-btn').click()");
  await sleep(250);
  await login('admin', 'admin123', 'admin');
  await sleep(300);
  shot = await cdp.send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync('/repo/College ERP System/screenshot-admin.png', Buffer.from(shot.data, 'base64'));
  console.log('screenshot-admin.png saved');

  const pass = results.filter((r) => r.pass).length;
  const fail = results.filter((r) => !r.pass).length;
  for (const r of results) console.log((r.pass ? 'PASS' : 'FAIL') + ' - ' + r.name);
  console.log(`\nTotal: ${results.length} | Pass: ${pass} | Fail: ${fail}`);

  chrome.kill();
  process.exit(fail > 0 ? 1 : 0);
}

main().catch((e) => {
  console.error('ERROR:', e.message);
  process.exit(1);
});

