arguments.content:
'use strict';
const http = require('http');
const { spawn } = require('child_process');

const PORT = 9228;
const FILE = 'file:///repo/College%20ERP%20System/index.html';
const profile = '/tmp/opencode/dbg-profile-' + Date.now();

function getJSON(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { reject(e); }
      });
    }).on('error', reject);
  });
}

class CDP {
  constructor(wsurl) {
    this.ws = new WebSocket(wsurl);
    this.id = 0;
    this.pending = new Map();
  }
  connect() {
    return new Promise((resolve, reject) => {
      this.ws.onopen = () => resolve();
      this.ws.onerror = () => reject(new Error('ws error'));
      this.ws.onmessage = (ev) => {
        const msg = JSON.parse(ev.data);
        if (msg.id && this.pending.has(msg.id)) {
          const { resolve, reject } = this.pending.get(msg.id);
          this.pending.delete(msg.id);
          if (msg.error) reject(new Error(JSON.stringify(msg.error)));
          else resolve(msg.result);
        }
      };
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => this.pending.set(id, { resolve, reject }));
  }
}

async function main() {
  const chrome = spawn('chromium', [
    '--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu',
    `--user-data-dir=${profile}`,
    `--remote-debugging-port=${PORT}`, '--window-size=1280,900', FILE
  ], { stdio: 'ignore' });

  let target;
  for (let i = 0; i < 40; i++) {
    try {
      const list = await getJSON(`http://127.0.0.1:${PORT}/json/list`);
      const page = list.find((t) => t.type === 'page' && t.url.startsWith('file:'));
      if (page) { target = page; break; }
    } catch (e) { /* retry */ }
    await new Promise((r) => setTimeout(r, 250));
  }

  const cdp = new CDP(target.webSocketDebuggerUrl);
  await cdp.connect();
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  await new Promise((r) => setTimeout(r, 1600));

  async function v(expr) {
    const res = await cdp.send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
    if (res.exceptionDetails) return 'EXC:' + JSON.stringify(res.exceptionDetails.exception);
    return res.result.value;
  }

  console.log('session:', await v("JSON.stringify(sessionStorage.getItem('collegeErpSession'))"));
  console.log('session var check:', await v("typeof session"));
  console.log('localData keys:', await v("Object.keys(localStorage).length"));
  console.log('login hidden class:', await v("document.getElementById('login-screen').className"));
  console.log('app hidden class:', await v("document.getElementById('app-screen').className"));
  console.log('page title:', await v("document.getElementById('page-title').textContent"));
  console.log('nav count:', await v("document.querySelectorAll('.nav-item').length"));
  console.log('url:', await v("location.href"));

  await cdp.send('Page.navigate', { url: FILE });
  await new Promise((r) => setTimeout(r, 1600));
  console.log('--- after navigate ---');
  console.log('session:', await v("JSON.stringify(sessionStorage.getItem('collegeErpSession'))"));
  console.log('login hidden class:', await v("document.getElementById('login-screen').className"));
  console.log('app hidden class:', await v("document.getElementById('app-screen').className"));
  console.log('URL:', await v("location.href"));

  chrome.kill();
  process.exit(0);
}

main().catch((e) => { console.error('ERROR:', e.message); process.exit(1); });

